'use client';

import React, { useState, FormEvent } from 'react';
import { useFirebase } from '@/context/FirebaseContext';
// import { useSocket } from '@/context/SocketContext.jsx';
import { loader } from "@/assets/icons/index.js";
import Diversity3Icon from '@mui/icons-material/Diversity3';
import { useRouter } from 'next/navigation';
import NextImage from 'next/image';

function CreateGroup() {
  const firebase = useFirebase();
  const router = useRouter();
  // const socket = useSocket();

  const [loading, setLoading] = useState<boolean>(false);
  const [username, setUsername] = useState<string>('');

  const handleGenerateRoom = async (e: FormEvent) => {
    e.preventDefault();
    if (loading) return;

    if (username.trim().length < 3) {
      alert("Name should be at least 3 characters long.");
      return;
    }

    setLoading(true);

    try {
      const roomId = await firebase.createRoomTransaction(username);
      if (roomId) {
        router.push(`/chat/${roomId}`);
      } else {
        alert("Failed to create room. Please try again.");
      }
    } catch (error) {
      console.error(error);
      alert("Something went wrong. Try again later.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <form onSubmit={handleGenerateRoom} className='flex flex-col gap-4 items-center w-full justify-center mb-5'>

        <div className='w-full'>
          <label htmlFor='username' className='sr-only'>Your Name</label>
          <input
            id="username"
            type="text"
            className='rounded-md border bg-transparent text-slate-100 w-full p-3'
            value={username}
            onChange={e => setUsername(e.target.value)}
            placeholder='Enter your name'
            disabled={loading}
            required
            aria-required="true"
            minLength={3}
          />
        </div>

        <div className='w-full'>
          <button
            type='submit'
            className='rounded-md border w-full h-[50px] text-white flex justify-center items-center backdrop-blur-sm hover:bg-white/20 transition-all p-3'
            disabled={loading}
            aria-busy={loading}
          >
            {loading ? (
              <div className='flex items-center gap-2'>
                <span>Creating...</span>
                <NextImage src={loader} width={23} alt="loading" />
              </div>
            ) : (
              <Diversity3Icon />
            )}
          </button>
        </div>

      </form>
    </div>
  );
}

export default CreateGroup;
